MISSING_RETURN_STATEMENT.example_broken:
public static int add(int a, int b) {
    int sum = a + b;
}

MISSING_RETURN_STATEMENT.example_fixed:
public static int add(int a, int b) {
    int sum = a + b;
    return sum;
}

STATIC_CONTEXT_ERROR.example_broken:
public class Main {
    int score = 100;
    public static void main(String[] args) {
        System.out.println(score);
    }
}

STATIC_CONTEXT_ERROR.example_fixed:
public class Main {
    static int score = 100;
    public static void main(String[] args) {
        System.out.println(score);
    }
}

